export const code = async (params) => {
  function hash(str) {
    let h = 5381;
    for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) | 0;
    return (h >>> 0).toString(16);
  }
  const results = params.search_gmail;
  const messages = results && Array.isArray(results.messages) ? results.messages : [];
  const emails = messages
    .map((m) => ({
      source: 'gmail',
      id: String(m?.id ?? ''),
      subject: String(m?.subject ?? ''),
      from: String(m?.from?.text ?? ''),
      date: String(m?.date ?? ''),
      body: String(m?.text ?? '').replace(/\s+/g, ' ').trim(),
      link: m?.id ? `https://mail.google.com/mail/u/0/#inbox/${m.id}` : '',
    }))
    .filter((c) => c.date && c.body.length > 0);
  let candidate = null;
  if (emails.length > 0) {
    emails.sort((a, b) => new Date(b.date) - new Date(a.date));
    candidate = emails[0];
  }
  if (!candidate) {
    const now = String(params.nowIso ?? new Date().toISOString());
    candidate = {
      source: 'demo',
      id: 'demo-transcript-acme',
      subject: 'Transcript: Acme Corp discovery call — pricing & rollout',
      from: 'nina.k@acmecorp.com',
      date: now,
      body: "Call transcript — Acme Corp discovery call\nDate: 2026-08-12\nParticipants: Ava (rep), Nina Kowalski (nina.k@acmecorp.com, CFO)\n\nAva: Thanks for making time today, Nina.\nNina: Happy to. We're evaluating tools for our sales ops team.\nAva: Great — what's the biggest pain point right now?\nNina: We lose follow-ups. Reps keep notes in five different places and drafts come out generic.\nAva: Understood. What would success look like?\nNina: One place for call notes and follow-ups, and drafts that reference our actual conversation.\nAva: We can do that. Roughly how many reps would use it?\nNina: About forty, starting with sales ops.\nAva: Any concerns before we go further?\nNina: Pricing is higher than our budget; we'd need a discount for a forty-seat rollout.\nAva: I'll talk to my manager about a volume discount and include it in the proposal.\nNina: If pricing works, we can pilot with sales ops by the end of next month.\nAva: I'll send over the proposal this week and set up a security review.\nNina: Sounds good. Send it directly to me.",
      link: 'https://mail.google.com/mail/u/0/#inbox/demo-transcript-acme',
    };
  }
  return {
    candidate,
    fingerprint: hash(candidate.date + '|' + candidate.from + '|' + candidate.body.slice(0, 2000)),
    found: true,
  };
};

